import json, time, sys, urllib.request, urllib.error
B = "http://localhost:8080"
tok = [None]
log = []
def get_token():
    r = urllib.request.Request(B + "/token", method="POST", data=b"")
    tok[0] = json.load(urllib.request.urlopen(r))["token"]
def req(path):
    for attempt in range(200):
        if tok[0] is None: get_token()
        r = urllib.request.Request(B + path, headers={"Authorization": "Bearer " + tok[0]})
        try:
            with urllib.request.urlopen(r) as resp:
                return json.load(resp)
        except urllib.error.HTTPError as e:
            body = e.read().decode()[:200]
            log.append((path, e.code, dict(e.headers).get("Retry-After"), body))
            if e.code == 404: return None
            if e.code == 401: tok[0] = None; continue
            ra = e.headers.get("Retry-After")
            try: w = float(ra)
            except: w = 1
            time.sleep(w)
        except Exception as e:
            log.append((path, "exc", str(e)))
            time.sleep(1)
    raise SystemExit("gave up " + path)

orders = []
page = 1
while True:
    d = req(f"/orders?page={page}")
    orders.append(d)
    if not d["next"]: break
    page += 1
json.dump(orders, open("/tmp/recon/pages.json", "w"))
cust = {}
ids = {o["customer_id"] for p in orders for o in p["items"]}
for c in sorted(ids):
    cust[c] = req(f"/customers/{c}")
json.dump(cust, open("/tmp/recon/cust.json", "w"))
print(len(orders), "pages", len(cust), "customers")
for l in log: print(l)
